ST.xhtml:p:
F_PowerOff(CLK := g_bDriveEnable);
IF F_PowerOff.Q THEN
  bSustainsPower1 := FALSE;
  bSustainsPower2 := FALSE;
  bSustainsPower3 := FALSE;
  bSustainsPower7 := FALSE;
  bSustainsPower8 := FALSE;
  bSustainsPower9 := FALSE;
END_IF;



IF g_Sustain1Power.Error THEN
  bSustainsPower1:= FALSE;
END_IF;

AxisPowerBrake(
	bPower := bSustainsPower1,
    AxisRef := REF(Axis_Sustain1),
    HomeSignal := g_nSustainHomeSignal1,
    HomeMode := g_nS1HomeMode,
    AxisPosLimit := NOT g_bSustain1PosLimit,
    AxisNegLimit := NOT g_bSustain1NegLimit,
    AxisPower := REF(g_Sustain1Power),
    OutBrake => g_boSupportAxis1HoldBrake);


IF g_Sustain2Power.Error THEN
  bSustainsPower2 := FALSE;
END_IF;
AxisPowerBrake1(
	bPower := bSustainsPower2,
    AxisRef := REF(Axis_Sustain2),
    HomeSignal := g_nSustainHomeSignal2,
    HomeMode := g_nS2HomeMode,
    AxisPosLimit := NOT g_bSustain2PosLimit,
    AxisNegLimit := NOT g_bSustain2NegLimit,
    AxisPower := REF(g_Sustain2Power),
    OutBrake => g_boSupportAxis2HoldBrake);


