IF ABS(Axis_Sustain1.NCTOPLC.ACTPOS - Axis_Sustain1.NCTOPLC.SETPOS) > g_fS1AxisMaxPosError THEN
  g_bS1AxisPosErrorAlarm := TRUE;
ELSE
  g_bS1AxisPosErrorAlarm := FALSE;
END_IF;
